-- Expanded Psionics Handbook powers M.
-- Concise mechanical summaries; XPH remains the source of record.

WITH desired(slug,name,discipline,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,description,augmentation_text) AS (VALUES
('major-creation-psionic','Major Creation, Psionic','metacreativity','creation','10 minutes','other','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'See referenced spell text','See spell text',NULL,NULL,'no',NULL,9,'Create nonmagical material as the major creation spell, using the psionic parameters stated in XPH.',NULL),
('matter-agitation','Matter Agitation','psychokinesis',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,'2 sq. ft. of surface area of an object or creature',NULL,'Concentration, up to 1 min./level',NULL,'None','yes',NULL,1,'Heat a small surface progressively while concentrating, escalating from ignition or minor burns to more serious heat damage.',NULL),
('matter-manipulation','Matter Manipulation','metacreativity',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,'1 cu. ft./level of inanimate material',NULL,'Instantaneous',NULL,'None','yes',NULL,15,'Permanently increase or decrease the hardness of mundane or magical inanimate material by as much as 5, with corresponding hit point changes.','XP cost: 250 XP per point of hardness altered.'),
('mental-barrier','Mental Barrier','clairsentience',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'1 round',NULL,NULL,'no',NULL,5,'Immediately gain a +4 deflection bonus to Armor Class.','Spend 4 additional PP to increase the AC bonus by 1; each additional PP can also extend duration by 1 round.'),
('mental-disruption','Mental Disruption','telepathy',NULL,'1 standard action','standard','10 ft.',NULL,'10-ft.-radius spread centered on you',NULL,'Instantaneous','will','Will negates','yes',NULL,3,'Emit a selective mental wave that dazes designated creatures in the area for 1 round on a failed Will save.','Every 2 additional PP can raise save DC by 1 and/or increase range and radius by 5 feet.'),
('metaconcert','Metaconcert','telepathy',NULL,'1 minute','other','20 ft.','You and up to nine other willing psionic creatures in range',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,9,'Link willing psionic creatures into a pooled mental entity with shared power points, access to participant powers, and scaling save/DC bonuses directed by a conductor.','Each additional PP increases duration by 1 minute.'),
('metafaculty','Metafaculty','clairsentience',NULL,'1 hour','other','Personal','You',NULL,NULL,'Instantaneous and 1 min./level (D); see text',NULL,NULL,'no',NULL,17,'Gain extraordinarily detailed information about a previously seen creature, including identity, rough power, location, possessions, recent activities, and a remote mental view.','XP cost: 1,000 XP.'),
('metamorphosis','Metamorphosis','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D) for a creature; 1 hour/level (D) for an object',NULL,NULL,'no',NULL,7,'Assume a qualifying creature or inanimate-object form, replacing physical ability scores and gaining the physical qualities and extraordinary attacks allowed by the power.',NULL),
('metamorphosis-greater','Metamorphosis, Greater','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D) for a creature; 1 hour/level (D) for an object',NULL,NULL,'no',NULL,17,'As metamorphosis, but assume nearly any nonunique creature or object from Fine to Colossal, gain extraordinary and supernatural abilities, and change forms once per round.','XP cost: 200 XP.'),
('metaphysical-claw','Metaphysical Claw','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level',NULL,NULL,'no',NULL,1,'Grant one claw or bite natural weapon a +1 enhancement bonus on attack and damage rolls.','Spend 4 additional PP to increase duration to 1 hour/level; every 4 additional PP also increases the enhancement bonus by 1.'),
('metaphysical-weapon','Metaphysical Weapon','metacreativity',NULL,'1 standard action','standard','Touch','Weapon touched',NULL,NULL,'1 min./level','will','Will negates (harmless, object)','yes','Yes (harmless, object)',1,'Grant a touched weapon, or a grouped set of projectiles, a +1 enhancement bonus on attack and damage rolls.','Spend 4 additional PP to increase duration to 1 hour/level; every 4 additional PP also increases the enhancement bonus by 1.'),
('microcosm','Microcosm','telepathy','compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature; see text','One or more creatures within a 15-ft.-radius sphere; see text',NULL,'Instantaneous',NULL,'None','yes',NULL,17,'Trap qualifying creatures inside fabricated internal sensory worlds, producing catatonia based on the single-target or area hit-point limits.','Each additional PP increases the individual and group hit-point thresholds by 10.'),
('mind-blank-personal','Mind Blank, Personal','telepathy',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'One day',NULL,NULL,'no',NULL,11,'Protect yourself as psionic mind blank, preventing effects that detect, influence, or read thoughts and emotions.','Psion/wilder base cost is 13 PP; psychic warrior base cost is 11 PP.'),
('mind-blank-psionic','Mind Blank, Psionic','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'One day','will','Will negates (harmless)','yes','Yes (harmless)',15,'Protect a creature from effects that detect, influence, or read emotions or thoughts, including most scrying and reality-altering attempts used for those purposes.',NULL),
('mind-probe','Mind Probe','telepathy','charm','1 minute','other','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 round/level (D)','will','Will partial; see text','yes',NULL,9,'Probe a subject’s memories and knowledge for one answer per round; successful Will saves let the subject resist individual questions without ending the power.',NULL),
('mind-seed','Mind Seed','telepathy','compulsion','1 standard action','standard','Touch','One touched Medium or smaller humanoid',NULL,NULL,'Instantaneous; see text','will','Will negates','yes',NULL,15,'Implant a copy of your psyche that germinates for one week and transforms the subject’s mind into a lower-level mental duplicate of you.','XP cost: 3,000 XP.'),
('mind-switch','Mind Switch','telepathy',NULL,'1 round','full_round','Close (25 ft. + 5 ft./2 levels)','You and one other creature',NULL,NULL,'10 min./level','will','Will negates; see text','yes',NULL,11,'Exchange minds with a nearby living creature, placing each psyche in the other body while retaining the class, mental, and learned traits defined by the power.','XP cost: 100 XP; every 2 additional PP increases save DC by 1.'),
('mind-switch-true','Mind Switch, True','telepathy',NULL,'1 minute','other','Close (25 ft. + 5 ft./2 levels)','You and one other creature',NULL,NULL,'Instantaneous','will','Will negates; see text','yes',NULL,17,'Permanently exchange bodies as mind switch, with the instantaneous duration preventing normal dispelling from restoring the original bodies.','XP cost: 10,000 XP.'),
('mind-thrust','Mind Thrust','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous','will','Will negates','yes',NULL,1,'Assault one creature’s thought pathways for 1d10 damage.','Each additional PP adds 1d10 damage; every extra 2d10 increases save DC by 1.'),
('mind-trap','Mind Trap','telepathy',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'1 round',NULL,'None','yes','Yes (harmless)',5,'Immediately trap your mind so a creature using a telepathy power against you loses 1d6 power points without negating its current power.','Each additional PP extends duration by 1 round.'),
('mindlink','Mindlink','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels); see text','You and one other willing creature with Intelligence 3 or higher',NULL,NULL,'10 min./level',NULL,'None; see text','yes','Yes (harmless)',1,'Forge a telepathic bond with a willing intelligent creature that functions across distance on the same plane.','Spend 4 additional PP to attempt an unwilling target; each additional PP can add another nearby target.'),
('mindlink-thieving','Mindlink, Thieving','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels); see text','You and one other creature',NULL,NULL,'10 min./level (D)','will','Will negates','yes',NULL,7,'As mindlink, but temporarily borrow one power known by a psionic subject and deny that power to the subject for the duration.','Every 2 additional PP increases save DC by 1.'),
('mindwipe','Mindwipe','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous','fort','Fortitude negates','yes',NULL,7,'Partially erase past experience, imposing two temporary negative levels and associated loss of highest-level power knowledge and reserve.','Every 2 additional PP can increase save DC by 1; every 3 additional PP adds one negative level.'),
('minor-creation-psionic','Minor Creation, Psionic','metacreativity','creation','1 minute','other','0 ft.',NULL,NULL,'Unattended nonpsionic nonmagical object of nonliving plant matter, up to 1 cu. ft./level','1 hour/level (D)',NULL,'None','no',NULL,1,'Create a temporary nonliving plant-matter object as the minor creation spell.',NULL),
('missive','Missive','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,'Mental message delivered to subject','Instantaneous (message delivery)',NULL,'None','yes',NULL,1,'Send a one-way telepathic message of up to ten words to one living creature in range.','Every 2 additional PP increases range by 5 feet and save DC by 1.'),
('missive-mass','Missive, Mass','telepathy',NULL,'1 standard action','standard','Long (400 ft. + 40 ft./level)','All selected creatures within range; see text',NULL,'Mental message delivered to subjects','Instantaneous (message delivery)','will','Will negates (harmless)','yes','Yes (harmless)',3,'Broadcast a one-way telepathic message of up to twenty-five words to included creatures within the large radius.','Every 2 additional PP increases range by 40 feet and save DC by 1.'),
('modify-memory-psionic','Modify Memory, Psionic','telepathy','compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Permanent','will','Will negates','yes',NULL,7,'Alter a creature’s memories as the modify memory spell.',NULL),
('moment-of-prescience-psionic','Moment of Prescience, Psionic','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level or until discharged',NULL,NULL,'no',NULL,13,'Gain the effects of moment of prescience psionically for the stated duration or until discharged.',NULL),
('my-light','My Light','psychokinesis',NULL,'1 standard action','standard','Personal','You',NULL,'20-ft. cone of light emanating from you','10 min./level (D)',NULL,NULL,'no',NULL,1,'Project a 20-foot cone of light from your eyes; elfsight extends the cone to 40 feet.','Spend 2 additional PP to manifest as a swift action.')
)
INSERT INTO dnd35_powers
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,discipline_id,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,augmentation_text,augmentation)
SELECT
  'xph-power-'||d.slug,'xph-3.5','Chapter 5',d.slug,d.name,d.description,d.description,0,NULL,1,
  'xph-power-discipline-'||d.discipline,d.subdiscipline,d.manifesting_time,d.action_type,d.range_text,
  d.target_text,d.area_text,d.effect_text,d.duration_text,d.save,d.saving_throw_text,
  d.power_resistance,d.power_resistance_text,d.power_points,d.augmentation_text,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_powers p
  WHERE p.slug=d.slug AND p.owner_user_id IS NULL
);
